"""Per-check prose for the checks added in 1.1.0: Laravel, multi-tenancy, business logic, performance and infrastructure.

Same format as check_text.py: ID: (in plain words, why it matters, fix, verify). check_text.py merges this table into T.
"""
T_NEW = {
"LARA-001": ("Laravel is set to show detailed error pages in production, which print your settings and code to anyone who triggers an error.", "Debug pages expose environment values, file paths and sometimes keys, and have been used to take over servers.", "Set APP_DEBUG=false and APP_ENV=production in the host's settings, remove committed environment files, and clear the config cache.", "Trigger a 500 on a staging copy: the page must show a plain error, not a stack trace."),
"LARA-002": ("The key Laravel uses to encrypt cookies and sign data is saved in the repository.", "Anyone with APP_KEY can read encrypted values and forge signed ones; in older versions it leads to remote code execution.", "Run `php artisan key:generate`, set the new key only in the host's secrets, remove the file from git and sign everyone out.", "scan_laravel is clean and `git ls-files` lists no environment file with values."),
"LARA-003": ("A model lets a request fill in any column, so a caller can add fields like `is_admin` or `company_id` to a normal form.", "Mass assignment turns a profile update into a privilege escalation or a move into another tenant.", "List only safe columns in `$fillable`, never roles or tenant IDs, and use validated data instead of `$request->all()`.", "A test that posts an extra `is_admin=1` field and checks it is ignored."),
"LARA-004": ("A raw SQL string contains a variable, so whoever controls the value can change the query.", "SQL injection reads or destroys the whole database and bypasses every access check.", "Use bindings (`whereRaw('x = ?', [$v])`) or the query builder; never join variables into the string.", "scan_laravel is clean; a test with a quote character in the input returns normally."),
"LARA-005": ("A Blade view prints a variable without escaping it, so HTML or script typed by a user runs in other people's browsers.", "Stored cross-site scripting steals sessions and acts as the visitor.", "Use `{{ $value }}`. If HTML is needed, sanitise it on save with a library such as HTML Purifier.", "Save `<script>alert(1)</script>` in the field and load the page: it must show as text."),
"LARA-006": ("API tokens can do everything and never expire.", "A leaked token gives permanent, full access to the account.", "Create tokens with a narrow ability list and expiry, set `expiration` in config/sanctum.php, and prune expired tokens.", "Config shows an expiry; a token without the ability gets 403."),
"LARA-007": ("A Livewire property holding an ID travels to the browser and back, so a user can change it to someone else's record.", "Livewire public properties are user-editable input, like form fields.", "Add `#[Locked]`, or set it in `mount()` and authorise the record on every action.", "A test that sets the property to another user's ID and calls the action gets 403."),
"LARA-008": ("A Livewire action changes data without asking whether the current user is allowed.", "Livewire actions can be called directly; hiding the button does not protect them.", "Call `$this->authorize()` first in every action that writes, and load records through the current user or tenant.", "Livewire test: acting as another user and calling the action fails with 403."),
"LARA-009": ("Roles or permissions are given out from request input with no check that the caller is allowed to.", "A normal user can make themselves an administrator.", "Authorise with a Gate or policy, validate the role against a fixed list and never assign what the request names unchecked.", "A non-admin posting a role gets 403 and the role is unchanged."),
"LARA-010": ("A controller saves request data without validating it.", "Wrong types, huge values and unexpected fields reach the database and cause errors or corrupted data.", "Use a Form Request with rules and `$request->validated()`.", "A test with missing and oversized fields gets 422."),
"LARA-011": ("An uploaded file is saved with the name or extension the uploader chose.", "A file called `shell.php` or with `../` in its name can overwrite files or be executed.", "Use `->store()` so Laravel picks the name, validate `mimes` and `max`, and keep uploads outside the public web root.", "Upload `a.php`: it is rejected or stored under a random safe name."),
"LARA-012": ("Request input is passed to a command, `eval` or `unserialize`.", "An attacker can run commands on your server or trigger code execution through crafted data.", "Remove the call, or use a safe library API; use `json_decode`, and `escapeshellarg` only as a last resort.", "scan_laravel is clean; a payload with `; id` in the input does nothing."),
"LARA-013": ("Form protection against other websites is switched off for the whole app.", "Another site can submit forms for a signed-in visitor.", "Exempt only the exact webhook paths and verify those with a signature.", "A cross-site form post to a protected route returns 419."),
"LARA-014": ("Any website may call your API from a visitor's browser with their cookies.", "A malicious page can read private data using the visitor's session.", "List your real front-end origins in `allowed_origins`.", "A request with an unknown Origin gets no CORS headers."),
"LARA-015": ("The Laravel version in use no longer gets security fixes.", "New vulnerabilities are published and never patched for it.", "Upgrade to a supported major version (Laravel 12 or later, support dates at laravel.com/docs/releases), then run the tests.", "`composer show laravel/framework` shows a supported major."),
"LARA-016": ("A permission rule always says yes.", "Every permission check in the app passes for everyone it covers.", "Return true only for a specific super-admin check and null otherwise, so normal policies still run.", "A normal user is denied an action protected by a policy."),
"LARA-017": ("Debugging tools that record requests and data are installed on production.", "Telescope, Debugbar and similar tools store sensitive requests and can expose them.", "Install them with `--dev`, deploy with `--no-dev`, and gate Telescope with a Gate if it must stay.", "`composer show --no-dev` does not list them."),
"API-020": ("Nothing limits how often someone can call the sign-in, password or data-changing routes.", "Unlimited attempts allow password guessing, code brute force and cost abuse.", "Add `throttle:` middleware or `$middleware->throttleApi()` and a named limiter keyed by IP and email for sign-in routes.", "The eleventh request in a minute gets 429."),
"API-021": ("A route picks a record by the ID in the URL and never checks that it belongs to the caller.", "Anyone signed in can read or change other people's records by changing the number (an IDOR).", "Add a policy and `$this->authorize()`, or load the record through the user's own relation.", "A test as user B requesting user A's record gets 403 or 404."),
"TEN-001": ("A table belongs to one company, but its model does not filter by company.", "Every query returns every customer's rows unless each developer remembers the filter every time.", "Add a global scope or trait that filters and fills the tenant column automatically.", "Two-tenant test: tenant A never sees tenant B's rows through the model."),
"TEN-002": ("A tenant filter is switched off in code that serves requests.", "That query reads all customers' data.", "Remove it or restrict it to an authorised, logged admin action.", "scan_tenancy is clean; the two-tenant test still passes."),
"TEN-003": ("A record is fetched by ID with no tenant condition.", "A user can open another company's record by guessing its ID.", "Look records up through the current tenant, or scope the model.", "Requesting another tenant's record ID returns 404."),
"TEN-004": ("The company or tenant comes from something the caller sends.", "Anyone can pass another company's ID and work inside it.", "Take the tenant from the signed-in user or a verified domain.", "A request naming another tenant is ignored or rejected."),
"TEN-005": ("A cached value comes from tenant data but its cache key is the same for everyone.", "The first company to load it fills the cache and the others are served its data.", "Include the tenant in the key or use per-tenant cache tags.", "Two tenants requesting the page see their own data."),
"TEN-006": ("A unique or exists rule checks the whole table, not the current tenant.", "It reveals that a value exists in another company and blocks values that other company uses.", "Add `->where('company_id', $tenantId)` to the rule.", "The same value can exist in two tenants."),
"TEN-007": ("The tenant column can be empty or has no index.", "Rows without a tenant are visible to everyone or no one, and scoped queries scan all customers.", "Make it NOT NULL with a foreign key and an index.", "The migration runs and `EXPLAIN` shows the index used."),
"BIZ-001": ("A balance or stock level is read, changed in PHP and written back without a lock.", "Two requests at once both read the old value, so money or stock is created or spent twice.", "Use a transaction with `lockForUpdate()` or atomic `decrement()` with a condition.", "A concurrency test firing two debits at once never overdraws."),
"BIZ-002": ("The code checks that something is free and then books it in a separate step.", "Two buyers asking at the same moment both pass the check and the last seat is sold twice.", "Check and write in one locked transaction and add a unique index on the slot.", "Two simultaneous bookings for one slot: one succeeds, one gets 409."),
"BIZ-003": ("A payment or transfer route does nothing about the same request arriving twice.", "Double clicks and retries after a timeout charge or pay twice.", "Require an idempotency key stored in a unique column and return the saved result on a repeat.", "Sending the same request twice moves money once."),
"BIZ-004": ("An amount is not limited to a positive range.", "A negative amount reverses a transfer and credits the sender.", "Add `min:0.01` and a `max`, and prefer integer cents.", "A request with -5 gets 422."),
"BIZ-005": ("Money is stored as a floating-point number.", "Floats cannot hold 0.10 exactly, so totals drift and balances stop matching.", "Use decimal columns or integer cents.", "Sum of ten 0.10 payments equals exactly 1.00."),
"BIZ-006": ("The client can send a price, total, discount or paid status that the server saves.", "Customers can set their own price to zero or mark an order as paid.", "Compute money fields on the server from product IDs and your own prices; change statuses only from verified events.", "Posting `price=0` does not change the stored price."),
"BIZ-007": ("A queued job that moves money can run twice.", "Queues re-deliver jobs after crashes and timeouts, so a payout can be paid twice.", "Make the job unique or record a processed marker in the same transaction.", "Dispatching the job twice changes the balance once."),
"PERF-007": ("Related records are fetched one row at a time inside a loop.", "A page with 100 rows runs 101 queries and slows with growth.", "Eager load with `with()`, and enable `preventLazyLoading` in development.", "Query count on the page is constant as rows grow."),
"PERF-008": ("A whole table is loaded into memory on a web request.", "Fine with 50 rows and fatal with 500,000.", "Use `paginate()`, `cursor()` or `chunk()` and select needed columns.", "The response time and memory stay flat as the table grows."),
"PERF-009": ("A query shape that cannot use an index or loads everything into PHP.", "It reads whole tables on every request.", "Aggregate in the database, avoid leading wildcards and random ordering, or use full-text search.", "`EXPLAIN` shows an index, and the query count and memory fall."),
"PERF-010": ("An email or notification is sent while the visitor waits.", "A slow mail server hangs the page and an outage makes the request fail.", "Queue the mail or notification and run a worker.", "The request returns before the mail is sent."),
"PERF-011": ("The queue, cache or session driver in production config is a development one.", "Queued jobs run inside the request, the cache caches nothing and sessions are lost.", "Use redis or database drivers and run a queue worker.", "A queued job is processed by the worker, not the request."),
"PERF-012": ("A column linking to another table has no index.", "Lookups, joins and deletes read the whole table.", "Use `foreignId()->constrained()` or add an index.", "`EXPLAIN` shows the index used."),
"INFRA-001": ("The web server serves the project folder, or lists folders.", "Visitors can request the environment file, logs and source code.", "Point the web root at `public`, deny dotfiles and turn off directory listing.", "`curl -I https://site/.env` returns 403 or 404."),
"INFRA-002": ("Encryption settings are old or certificate checks are off, or there is no HTTPS redirect.", "Passwords and sessions can be read or changed in transit.", "Use TLS 1.2 and 1.3, redirect HTTP to HTTPS, and never disable certificate verification.", "An SSL scan grades A and `http://` redirects."),
"INFRA-003": ("Build or deploy steps make files world-writable.", "Any process on the machine, including a hijacked web request, can change your code.", "Give the web user write access only to `storage` and `bootstrap/cache`.", "`find . -perm -o+w` lists nothing outside those folders."),
"INFRA-004": ("The scheduler or queue worker has no process that runs it.", "Scheduled tasks and queued emails silently never run.", "Run `schedule:run` from cron (or `schedule:work`) and `queue:work` under a process manager.", "A test task and a test job run on the server."),
"INFRA-005": ("Scheduled tasks can overlap, or fail without anyone being told.", "Overlapping runs double work or corrupt data; silent failures go unnoticed for weeks.", "Add `withoutOverlapping()`, `onOneServer()` and a failure hook or heartbeat.", "A failing task sends an alert."),
"INFRA-006": ("No database backup job is defined.", "Data loss then means starting from nothing.", "Schedule daily backups stored off the server, monitor them and practise a restore.", "A restored copy opens in a scratch database."),
"INFRA-007": ("The deploy installs development packages or skips Laravel's optimisation.", "Debug packages and their vulnerabilities reach production and every request is slower.", "Use `composer install --no-dev --optimize-autoloader` and `php artisan optimize`.", "`composer show --no-dev` lists no dev tools and caches exist."),
"INFRA-008": ("A database or cache port is open to the internet, or uses a default password.", "Attackers scan for these and log in or wipe the data.", "Do not publish the port, firewall it and set long random passwords.", "`nmap` from outside shows the port closed."),
"INFRA-009": ("Logs go to one file that grows for ever.", "A noisy day can fill the disk and stop the server.", "Use the `daily` channel with a retention, or ship logs elsewhere.", "Old log files are removed after the retention period."),
}
